losses = [0.9, 0.7, 0.55, 0.5, 0.52, 0.6, 0.45]
best = 999
for epoch in range(1, len(losses) + 1):
    loss = losses[epoch - 1]
    if loss < best:
        best = loss
        print(f"Epoch {epoch}: loss {loss}")
    else:
        print(f"Early stop at epoch {epoch}, best loss {best}")
        break

